clc, clearvars, close all

dicesX(10) %[output:142da47e]
%%
clc, clearvars, close all

global x y z;

x = 0:0.1:20;

calculateY;
calculateZ;

figure; %[output:2dab80e8]
plot(x, z, 'b-.o'); %[output:2dab80e8]
grid on; %[output:2dab80e8]
xlabel('x'); %[output:2dab80e8]
ylabel('z'); %[output:2dab80e8]
title('z = sqrt(x^2)'); %[output:2dab80e8]
legend('z = sqrt(y)'); %[output:2dab80e8]

whos %[output:205410eb]
%%
clc, clearvars, close all
x = 0:0.1:2*pi;
grafsincos(x) %[output:7a13e115]
%%
[s, c] = grafsincos(x);
disp(s); %[output:3f2ce27f]
disp(c); %[output:2cbd806b]
%%
s = grafsincos(x);
disp(s); %[output:586fa7dc]
%%
grafsincos(1, 2) %[output:2bfd5243]
grafsincos([1; 2; 3]) % supposed to error

